INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Testen Unit-Tests immer das gesamte System?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Einzelfunktionen"}, {"text": "Ja", "correct": false, "because": "Fokus auf Komponenten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Unit-Tests?', 3, '[{"text": "Funktionalität einzelner Teile prüfen", "correct": true, "because": "Isoliert testen"}, {"text": "Systemintegration validieren", "correct": false, "because": "Für Integrationstests"}, {"text": "UI gestalten", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Unit-Tests?', 5, '[{"text": "Assertions", "correct": true, "because": "Überprüfen Ergebnisse"}, {"text": "Testfälle", "correct": true, "because": "Definieren Szenarien"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Assertions prüfen Erwartungen. b) Unit-Tests brauchen Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "DB optional"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Unit-Tests?', 4, '[{"text": "Testabdeckung", "correct": false, "because": "Sichert Qualität"}, {"text": "Assertions", "correct": false, "because": "Überprüfen Ergebnisse"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unit-Tests Abhängigkeiten testen?', 2, '[{"text": "Nein", "correct": true, "because": "Isolierte Funktionen"}, {"text": "Ja", "correct": false, "because": "Für Integrationstests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine Assertion in Python?', 3, '[{"text": "assert", "correct": true, "because": "Prüft Bedingung"}, {"text": "print", "correct": false, "because": "Nur Ausgabe"}, {"text": "return", "correct": false, "because": "Beendet Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Unit-Tests?', 5, '[{"text": "Fehlerfrüherkennung", "correct": true, "because": "Findet Bugs früh"}, {"text": "Wartbarkeit", "correct": true, "because": "Sichert Refactoring"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Unit-Tests sind isoliert. b) Sie testen immer UI. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "UI separat"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Unit-Tests?', 4, '[{"text": "Testframework", "correct": false, "because": "Strukturiert Tests"}, {"text": "Assertions", "correct": false, "because": "Validieren Ergebnisse"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Testen Unit-Tests Abhängigkeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Isolation"}, {"text": "Ja", "correct": false, "because": "Andere Testarten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben gute Unit-Tests?', 4, '[{"text": "Unabhängigkeit", "correct": true, "because": "Isoliert laufen"}, {"text": "Wiederholbarkeit", "correct": true, "because": "Konsistente Ergebnisse"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Testkriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Unit-Tests langsam sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schnell durch Isolation"}, {"text": "Ja", "correct": false, "because": "Meist effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Unit-Tests?', 3, '[{"text": "Klarheit der Assertions", "correct": true, "because": "Sichert Verständnis"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Korrektheit zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unit-Tests brauchen Mocking. b) Assertions sind optional.', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) optional, b) essenziell"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Unit-Tests?', 5, '[{"text": "Unentdeckte Fehler", "correct": true, "because": "Keine frühzeitige Prüfung"}, {"text": "Schwerere Wartung", "correct": true, "because": "Änderungen unsicher"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Unit-Tests unwichtig?', 3, '[{"text": "Testfälle", "correct": false, "because": "Definieren Prüfungen"}, {"text": "Assertions", "correct": false, "because": "Validieren Ergebnisse"}, {"text": "Serverleistung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Unit-Tests manuell geschrieben werden?', 3, '[{"text": "Nein", "correct": true, "because": "Tools können generieren"}, {"text": "Ja", "correct": false, "because": "Automatisierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unit-Tests UI testen?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Logik"}, {"text": "Ja", "correct": false, "because": "Für UI-Tests separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework wähle ich für Unit-Tests in Python?', 4, '[{"text": "unittest", "correct": true, "because": "Standardbibliothek"}, {"text": "json", "correct": false, "because": "Datenformat"}, {"text": "css", "correct": false, "because": "Styling"}]');
